    dict(key='29-class-4', kind='code', title='AbsoluteTimeoutFilter — too old, however busy',
         body='// AbsoluteTimeoutFilter: the 8-hour limit Spring Session lacks\nif (session != null && tooOld(session)) {\n    session.invalidate();\n...\nInstant created = Instant.ofEpochMilli(session.getCreationTime());\nreturn created.plus(limit).isBefore(clock.instant());',
         narration="On every request, the filter adds eight hours to the session's creation time. [[slnc 300]] If that is already past, the session is ended, however recently it was used."),
